INSERT INTO Language_en_US(Tag,Text) VALUES
 ('TXT_KEY_CWC3_CIV','The Ministry of Almost'),
 ('TXT_KEY_CWC3_SHORT','Ministry of Almost'),
 ('TXT_KEY_CWC3_ADJECTIVE','Ministerial'),
 ('TXT_KEY_CWC3_LEADER','Acting Chancellor Penultimate'),
 ('TXT_KEY_CWC3_TRAIT','Always the Challenger'),
 ('TXT_KEY_CWC3_TRAIT_HELP','At the beginning of each owner-turn, compare researched technologies with the leading living rival major team. At 0-2 technologies behind: no bonus. At 3-5: +1 [ICON_RESEARCH] Science and +1 [ICON_CULTURE] Culture in every city. At 6 or more: +2 Science and +1 Culture in every city. Bonuses are capped, do not stack, and disappear as you catch up. Your own team, city-states, barbarians and eliminated civilizations are excluded.'),
 ('TXT_KEY_CWC3_CIV_PEDIA','Second Place Is Just First Place in Disguise.[NEWLINE][NEWLINE]The Ministry of Almost is a fictional bureaucratic republic with a treasury full of silver medals. Narrow defeats became lessons, delayed discoveries inspired better schools, and emergency educational improvements helped the country recover whenever another nation pulled far ahead. Its institutions reward recovery rather than permanent disadvantage. When the Ministry catches up, its emergency programs close.'),
 ('TXT_KEY_CWC3_STRATEGY','Build a normal Science or Culture economy. Temporary catch-up yields support recovery; they cannot replace growth, Libraries, Universities, specialists and defensive preparation. Never delay important research to enlarge the gap.'),
 ('TXT_KEY_CWC3_LEADER_PEDIA','Acting Chancellor Penultimate has served for forty-seven years without winning an election. Every election she loses by exactly one vote; every victor resigns before taking office. A middle-aged woman in an elaborate silver ceremonial uniform, she presides beneath the portrait of the first Chancellor, surrounded by hundreds of silver medals. Repeated disappointment has made her a patient, exceptionally competent administrator.'),
 ('TXT_KEY_CWC3_UNIT','Second Wind Guard'),
 ('TXT_KEY_CWC3_UNIT_HELP','Replaces the Spearman, retaining its active Community Patch properties and normal upgrades, with exactly +1 Movement. Second Wind veterans gain +15% defensive strength while occupying territory owned by their own team. This bonus never increases attack strength and is removed outside team-owned territory. The veteran identity survives normal upgrades; the extra Movement does not.'),
 ('TXT_KEY_CWC3_UNIT_PEDIA','We''re Not Finished Yet![NEWLINE][NEWLINE]These mobile defensive troops protect schools and government offices while the Ministry rebuilds. Each regiment carries a silver medal from a campaign it almost won. Their discipline survives promotion to more modern service.'),
 ('TXT_KEY_CWC3_UNIT_STRATEGY','Use the additional Movement to reinforce threatened friendly cities. Fight defensively on your own territory. Normal Spearman strengths and weaknesses still apply.'),
 ('TXT_KEY_CWC3_ACADEMY','Runner-Up Academy'),
 ('TXT_KEY_CWC3_ACADEMY_HELP','Replaces the Library and retains every normal effect of the active Community Patch Library. Adds +1 [ICON_CULTURE] Culture permanently. Adds exactly +1 [ICON_PRODUCTION] Production while the current owner-turn snapshot is six or more technologies behind, provided the Ministry owns this city. The temporary Production disappears if the Academy is lost.'),
 ('TXT_KEY_CWC3_ACADEMY_PEDIA','Excellence Is a Work in Progress.[NEWLINE][NEWLINE]Every lecture begins with a failed experiment and ends with an improved proposal. Silver medals decorate the reading rooms. The Academy supplies ordinary Library education alongside a lasting cultural tradition and temporary industrial training during serious technological disadvantage.'),
 ('TXT_KEY_CWC3_ACADEMY_STRATEGY','Build early for normal Library Science and permanent Culture. At a gap of six, the Academy also supplies one temporary Production. Plan an economy that can succeed after this bonus ends.'),
 ('TXT_KEY_CWC3_IDENTITY','Second Wind Veteran'),
 ('TXT_KEY_CWC3_IDENTITY_HELP','Retains the Second Wind Guard defensive benefit through normal upgrades. +15% defense while standing in team-owned territory; no attack bonus.'),
 ('TXT_KEY_CWC3_DEFENSE','Second Wind: Home Defense'),
 ('TXT_KEY_CWC3_DEFENSE_HELP','+15% defensive strength on team-owned territory. No attack strength modifier. Removed on leaving qualifying territory.'),
 ('TXT_KEY_CWC3_DUMMY','Ministry Emergency Program'),
 ('TXT_KEY_CWC3_DUMMY_HELP','Internal recurring yield controller. Unbuildable; managed by the current owner-turn snapshot.'),
 ('TXT_KEY_CWC3_GREETING_1','Welcome! You''re actually our second diplomatic visitor today. The first one cancelled, so technically you''re first! Congratulations!'),
 ('TXT_KEY_CWC3_WAR_1','We have tolerated second place for centuries. Unfortunately for you, we have decided to pursue a different ranking.'),
 ('TXT_KEY_CWC3_DEFEAT_1','Second place... again? Wait. How many civilizations are left?'),
 ('TXT_KEY_CWC3_PEACE_1','A compromise. An outcome in which neither side comes first. We approve.'),
 ('TXT_KEY_CWC3_FRIENDLY_1','Your proposal has reached the second round of consideration. This is a very good sign.'),
 ('TXT_KEY_CWC3_NEUTRAL_1','The Ministry has received your papers. Please take a silver number.'),
 ('TXT_KEY_CWC3_HOSTILE_1','We have nearly exhausted our patience.'),
 ('TXT_KEY_CWC3_ATTACKED_1','You have mistaken patience for surrender. The Ministry will try again.'),
 ('TXT_KEY_CWC3_TRADE_1','An almost perfect agreement. We accept.'),
 ('TXT_KEY_CWC3_DAWN','Honorable Acting Chancellor Penultimate, your people await your next attempt at greatness.[NEWLINE][NEWLINE]Throughout history, civilizations have celebrated their greatest victories, their most brilliant discoveries and their most glorious achievements.[NEWLINE][NEWLINE]Your people have experienced something rather different.[NEWLINE][NEWLINE]They have finished second.[NEWLINE][NEWLINE]Again and again, the Ministry has approached greatness, only to watch another nation claim the prize moments before them.[NEWLINE][NEWLINE]Yet your citizens have never surrendered to disappointment.[NEWLINE][NEWLINE]Every defeat became a lesson. Every failure became an opportunity. Every setback inspired another attempt.[NEWLINE][NEWLINE]Now, the Ministry stands ready to challenge the greatest civilizations in history.[NEWLINE][NEWLINE]Build your cities. Educate your citizens. Transform yesterday''s failures into tomorrow''s achievements.[NEWLINE][NEWLINE]Will your civilization finally claim first place?[NEWLINE][NEWLINE]Or will history remember you as the greatest runner-up of all time?'),
 ('TXT_KEY_CWC3_CITY_1','Runner-Up'),
 ('TXT_KEY_CWC3_CITY_2','Silverhaven'),
 ('TXT_KEY_CWC3_CITY_3','Near Victory'),
 ('TXT_KEY_CWC3_CITY_4','Penultimate'),
 ('TXT_KEY_CWC3_CITY_5','Second Crossing'),
 ('TXT_KEY_CWC3_CITY_6','Almostopolis'),
 ('TXT_KEY_CWC3_CITY_7','Honorable Mention'),
 ('TXT_KEY_CWC3_CITY_8','Next Attempt'),
 ('TXT_KEY_CWC3_CITY_9','Narrow Margin'),
 ('TXT_KEY_CWC3_CITY_10','Provisional Bay'),
 ('TXT_KEY_CWC3_CITY_11','Deferred Glory'),
 ('TXT_KEY_CWC3_CITY_12','Another Chance'),
 ('TXT_KEY_CWC3_CITY_13','Silver Standard'),
 ('TXT_KEY_CWC3_CITY_14','Rising Again'),
 ('TXT_KEY_CWC3_CITY_15','Final Draft'),
 ('TXT_KEY_CWC3_CITY_16','Better Tomorrow'),
 ('TXT_KEY_CWC3_CITY_17','Second Dawn'),
 ('TXT_KEY_CWC3_CITY_18','The Waiting Room'),
 ('TXT_KEY_CWC3_CITY_19','Last Revision'),
 ('TXT_KEY_CWC3_CITY_20','Resilience'),
 ('TXT_KEY_CWC3_CITY_21','Hopeful Assembly'),
 ('TXT_KEY_CWC3_CITY_22','Medalford'),
 ('TXT_KEY_CWC3_CITY_23','The Finalist'),
 ('TXT_KEY_CWC3_CITY_24','Tomorrow First'),
 ('TXT_KEY_CWC3_SPY_1','Deputy'),
 ('TXT_KEY_CWC3_SPY_2','Alternate'),
 ('TXT_KEY_CWC3_SPY_3','Reserve'),
 ('TXT_KEY_CWC3_SPY_4','Acting'),
 ('TXT_KEY_CWC3_SPY_5','Interim'),
 ('TXT_KEY_CWC3_SPY_6','Standby'),
 ('TXT_KEY_CWC3_SPY_7','Silver'),
 ('TXT_KEY_CWC3_SPY_8','Almost'),
 ('TXT_KEY_CWC3_SPY_9','Runner'),
 ('TXT_KEY_CWC3_SPY_10','Second'),
 ('TXT_KEY_CWC3_CIV5_HEADING_1','The Republic of Second Chances'),
 ('TXT_KEY_CWC3_CIV5_TEXT_1','Second Place Is Just First Place in Disguise.[NEWLINE][NEWLINE]The Ministry of Almost is a fictional bureaucratic republic with a treasury full of silver medals. Narrow defeats became lessons, delayed discoveries inspired better schools, and emergency educational improvements helped the country recover whenever another nation pulled far ahead. Its institutions reward recovery rather than permanent disadvantage. When the Ministry catches up, its emergency programs close.'),
 ('TXT_KEY_CWC3_CIV5_HEADING_2','Always the Challenger'),
 ('TXT_KEY_CWC3_CIV5_TEXT_2','At the beginning of each owner-turn, compare researched technologies with the leading living rival major team. At 0-2 technologies behind: no bonus. At 3-5: +1 [ICON_RESEARCH] Science and +1 [ICON_CULTURE] Culture in every city. At 6 or more: +2 Science and +1 Culture in every city. Bonuses are capped, do not stack, and disappear as you catch up. Your own team, city-states, barbarians and eliminated civilizations are excluded.'),
 ('TXT_KEY_CWC3_CIV5_FACTOID_HEADING','The Silver Standard'),
 ('TXT_KEY_CWC3_CIV5_FACTOID_TEXT','The Ministry records every near victory so that no useful lesson is lost.'),
 ('TXT_KEY_CWC3_PENULTIMATE_NAME','Acting Chancellor Penultimate'),
 ('TXT_KEY_CWC3_PENULTIMATE_SUBTITLE','The Perpetual Acting Chancellor'),
 ('TXT_KEY_CWC3_PENULTIMATE_LIVED','Fictional leader; forty-seven years in acting office'),
 ('TXT_KEY_CWC3_PENULTIMATE_TITLES_1','Acting Chancellor of the Ministry of Almost'),
 ('TXT_KEY_CWC3_PENULTIMATE_HEADING_1','A Competent Runner-Up'),
 ('TXT_KEY_CWC3_PENULTIMATE_TEXT_1','Acting Chancellor Penultimate has served for forty-seven years without winning an election. Every election she loses by exactly one vote; every victor resigns before taking office. A middle-aged woman in an elaborate silver ceremonial uniform, she presides beneath the portrait of the first Chancellor, surrounded by hundreds of silver medals. Repeated disappointment has made her a patient, exceptionally competent administrator.'),
 ('TXT_KEY_CWC3_PENULTIMATE_FACT_1','Every winning candidate resigns before taking office.');
